static NSError *Err(NSString *s){return [NSError errorWithDomain:@"TweakForge.AI.Attachments" code:1 userInfo:@{NSLocalizedDescriptionKey:s}];}
static NSString *Hash(NSData *d){unsigned char h[32];CC_SHA256(d.bytes,(CC_LONG)d.length,h);NSMutableString *s=[NSMutableString new];for(int i=0;i<32;i++)[s appendFormat:@"%02x",h[i]];return s;}
static NSString *Store(void){return [NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory,NSUserDomainMask,YES).firstObject stringByAppendingPathComponent:@"TweakForgeAI/Attachments"] ;}
static BOOL Excluded(NSString *p){for(NSString *part in p.pathComponents){NSString *s=part.lowercaseString;if([s hasPrefix:@"."]||[s hasPrefix:@"build-"]||[s hasPrefix:@"snapshot-"]||[s containsString:@"credential"]||[s containsString:@"secret"]||[s containsString:@"token"]||[@[@"build",@"deriveddata",@"frameworks",@"node_modules",@"caches",@"tmp",@"auth.json",@"id_rsa",@"id_ed25519"] containsObject:s])return YES;}return [@[@"ipa",@"o",@"a",@"p12",@"pfx",@"pem",@"key",@"cer",@"mobileprovision",@"zip",@"7z",@"rar"] containsObject:p.pathExtension.lowercaseString];}
static NSString *Media(NSString *p){if([@[@"deb",@"dylib"] containsObject:p.pathExtension.lowercaseString])return @"artifact";NSString *e=p.pathExtension.lowercaseString;if([@[@"png",@"jpg",@"jpeg",@"heic",@"gif",@"webp"] containsObject:e])return @"image";if([@[@"txt",@"log",@"ips",@"json",@"plist",@"m",@"mm",@"xm",@"x",@"h",@"hpp",@"c",@"cpp",@"cc",@"md",@"yaml",@"yml",@"swift",@"html",@"css",@"js",@"ts"] containsObject:e]||[@[@"makefile",@"control",@"readme",@"license"] containsObject:p.lastPathComponent.lowercaseString])return @"text";return nil;}
BOOL TFAIAttachmentSensitive(NSString *text){NSRegularExpression *r=[NSRegularExpression regularExpressionWithPattern:@"(?i)(github_pat_[a-z0-9_]{12,}|gh[pousr]_[a-z0-9]{20,}|sk-(?:proj-|ant-)?[a-z0-9_-]{20,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|authorization[\\\"'\\s:]+(?:bearer|basic)\\s+[a-z0-9._+/=-]{12,})" options:0 error:nil];return [r firstMatchInString:text options:0 range:NSMakeRange(0,text.length)]!=nil;}
static NSString *Safe(NSString *root,NSString *relative,NSError **error){if(![relative isKindOfClass:NSString.class]||!relative.length||relative.isAbsolutePath||[relative containsString:@"\\"]||Excluded(relative)||[relative.pathComponents containsObject:@".."]){if(error)*error=Err(@"附件路径包含敏感文件或越界内容");return nil;}NSString *base=root.stringByStandardizingPath.stringByResolvingSymlinksInPath,*walk=base;for(NSString *part in relative.pathComponents){walk=[walk stringByAppendingPathComponent:part];NSDictionary *a=[NSFileManager.defaultManager attributesOfItemAtPath:walk error:nil];if([a[NSFileType] isEqual:NSFileTypeSymbolicLink]){if(error)*error=Err(@"附件不跟随符号链接");return nil;}}if(![walk.stringByResolvingSymlinksInPath hasPrefix:[base stringByAppendingString:@"/"]]){if(error)*error=Err(@"附件超出所选目录");return nil;}return walk;}
NSArray *TFAIAttachmentCandidates(NSString *root,NSError **error){NSFileManager *fm=NSFileManager.defaultManager;NSMutableArray *out=[NSMutableArray new];NSDirectoryEnumerator *en=[fm enumeratorAtPath:root];NSUInteger visited=0;for(NSString *p in en){if(++visited>10000){if(error)*error=Err(@"目录超过 10000 项，请选择较小的内部文件夹");return nil;}if(Excluded(p)){[en skipDescendants];continue;}NSString *full=Safe(root,p,nil);if(!full){[en skipDescendants];continue;}NSDictionary *a=[fm attributesOfItemAtPath:full error:nil];if([a[NSFileType] isEqual:NSFileTypeDirectory])continue;if(![a[NSFileType] isEqual:NSFileTypeRegular]||!Media(p))continue;[out addObject:@{@"relativePath":p,@"bytes":a[NSFileSize]?:@0,@"media":Media(p)}];}return [out sortedArrayUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [a[@"relativePath"] localizedStandardCompare:b[@"relativePath"]];}];}
static NSDictionary *Stage(NSData *data,NSString *relative,NSString *source,NSError **error){NSString *media=Media(relative);NSUInteger originalBytes=data.length;NSDictionary *binary=nil;BOOL artifact=[media isEqual:@"artifact"];if(artifact){NSDictionary *inspection=TFAIInspectArtifact(data,relative,error);if(!inspection)return nil;if([relative.pathExtension.lowercaseString isEqual:@"dylib"]){binary=TFAIBinaryStage(data,relative,error);if(!binary)return nil;}data=[NSJSONSerialization dataWithJSONObject:inspection options:NSJSONWritingPrettyPrinted error:error];if(!data)return nil;media=@"text";}if(!media||Excluded(relative)){if(error)*error=Err(@"支持图片、文本、源码及 deb / dylib 本机检查；凭据已排除");return nil;}if(data.length>20*1024*1024){if(error)*error=Err(@"图片和本机文本副本单文件上限 20 MB");return nil;}if(!data){if(error)*error=Err(@"附件读取失败");return nil;}if([media isEqual:@"text"]){NSString *text=[[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];if(!text||[text rangeOfString:[NSString stringWithFormat:@"%C",(unichar)0]].location!=NSNotFound||TFAIAttachmentSensitive(text)){if(error)*error=Err(@"文本编码不符或含疑似密钥，未导入");return nil;}}
 NSString *identifier=NSUUID.UUID.UUIDString;if([source isEqual:@"外部参考"])source=[source stringByAppendingFormat:@"·%@",[identifier substringToIndex:6]];NSString *name=[identifier stringByAppendingPathExtension:relative.pathExtension];NSString *target=[Store() stringByAppendingPathComponent:name];if(![NSFileManager.defaultManager createDirectoryAtPath:Store() withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700} error:error]||![data writeToFile:target options:NSDataWritingAtomic error:error])return nil;[NSFileManager.defaultManager setAttributes:@{NSFilePosixPermissions:@0600} ofItemAtPath:target error:nil];return @{@"kind":@"reference",@"id":identifier,@"storageName":name,@"sourceName":source,@"relativePath":relative,@"path":[NSString stringWithFormat:@"%@ / %@",source,relative],@"bytes":@(data.length),@"media":media,@"sha256":Hash(data),@"state":@"importedLocal",@"referenceOnly":@YES,@"artifactInspection":@(artifact),@"binaryInputID":binary[@"binaryInputID"]?:@"",@"originalBytes":@(originalBytes)};}
NSArray *TFAIStageAttachmentFiles(NSString *root,NSArray *paths,NSString *source,NSError **error){if(paths.count>80){if(error)*error=Err(@"每次最多选择 80 个文件");return nil;}NSMutableArray *out=[NSMutableArray new];NSUInteger total=0;for(NSString *rel in paths){NSString *p=Safe(root,rel,error);if(!p)goto fail;NSDictionary *a=[NSFileManager.defaultManager attributesOfItemAtPath:p error:error];if(![a[NSFileType] isEqual:NSFileTypeRegular]){if(error)*error=Err(@"仅可导入普通文件");goto fail;}NSUInteger cap=[Media(rel) isEqual:@"artifact"]?64*1024*1024:20*1024*1024;if([a[NSFileSize] unsignedLongLongValue]>cap){if(error)*error=Err([NSString stringWithFormat:@"%@ 为 %.1f MB，超过该类型单文件上限 %.0f MB。请取消此文件或选择其他文件。",rel,[a[NSFileSize] doubleValue]/1024/1024,cap/1024.0/1024]);goto fail;}NSData *data=[NSData dataWithContentsOfFile:p options:NSDataReadingMappedIfSafe error:error];if(!data)goto fail;total+=data.length;if(total>128*1024*1024){if(error)*error=Err(@"本次导入超过 128 MB，请减少选择");goto fail;}NSDictionary *entry=Stage(data,rel,source,error);if(!entry){if(error&&*error)*error=Err([NSString stringWithFormat:@"%@：%@",rel,(*error).localizedDescription]);goto fail;}[out addObject:entry];}return out;
 fail:for(NSDictionary *entry in out)[NSFileManager.defaultManager removeItemAtPath:[Store() stringByAppendingPathComponent:entry[@"storageName"]] error:nil];return nil;}
NSString *TFAIAttachmentLocalPath(NSDictionary *entry,NSError **error){NSString *n=entry[@"storageName"];if(![n isKindOfClass:NSString.class]||![n isEqual:n.lastPathComponent]||![[NSUUID alloc] initWithUUIDString:n.stringByDeletingPathExtension]){if(error)*error=Err(@"附件引用无效");return nil;}NSString *p=[Store() stringByAppendingPathComponent:n];NSDictionary *a=[NSFileManager.defaultManager attributesOfItemAtPath:p error:nil];if(![a[NSFileType] isEqual:NSFileTypeRegular]||[a[NSFileSize] unsignedLongLongValue]>20*1024*1024){if(error)*error=Err(@"本机附件已丢失或类型改变，请重新导入");return nil;}return p;}
NSArray *TFAIResolveAttachments(NSArray *entries,NSError **error){if(![entries isKindOfClass:NSArray.class]){if(error)*error=Err(@"附件列表格式不符");return nil;}if(entries.count>80){if(error)*error=Err(@"附件超过 80 项");return nil;}NSMutableArray *out=[NSMutableArray new];NSUInteger textBytes=0,total=0;for(NSDictionary *entry in entries){if(![entry isKindOfClass:NSDictionary.class]||![entry[@"kind"] isKindOfClass:NSString.class]||![entry[@"path"] isKindOfClass:NSString.class]){if(error)*error=Err(@"附件记录格式不符，请移除后重新导入");return nil;}NSDictionary *resolved=nil;if([entry[@"kind"] isEqual:@"directory"]){if(!TFAIReadDirectoryReference(entry,@{@"action":@"validate"},error))return nil;[out addObject:entry];continue;}if([entry[@"kind"] isEqual:@"reference"]){NSString *p=TFAIAttachmentLocalPath(entry,error);if(!p)return nil;NSData *data=[NSData dataWithContentsOfFile:p options:0 error:error];if(!data||![Hash(data) isEqual:entry[@"sha256"]]){if(error)*error=Err(@"附件副本已变化，请重新导入确认");return nil;}if([entry[@"media"] isEqual:@"text"]){NSString *text=[[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];if(!text||TFAIAttachmentSensitive(text)){if(error)*error=Err(@"附件包含敏感内容，已停止发送");return nil;}NSMutableDictionary *reference=[@{@"path":entry[@"path"],@"kind":@"text",@"bytes":@(data.length),@"sourceName":entry[@"sourceName"]?:@"参考附件",@"referenceOnly":@YES,@"binaryInputID":entry[@"binaryInputID"]?:@"",@"localSnapshot":[entry copy]} mutableCopy];if(data.length<=256*1024)reference[@"content"]=text;resolved=reference;}else{
#if __has_include(<UIKit/UIKit.h>)
 CGImageSourceRef source=CGImageSourceCreateWithData((__bridge CFDataRef)data,NULL);CGImageRef thumb=source?CGImageSourceCreateThumbnailAtIndex(source,0,(__bridge CFDictionaryRef)@{(id)kCGImageSourceCreateThumbnailFromImageAlways:@YES,(id)kCGImageSourceThumbnailMaxPixelSize:@1600,(id)kCGImageSourceCreateThumbnailWithTransform:@YES}):NULL;if(source)CFRelease(source);if(!thumb){if(error)*error=Err(@"图片解码失败");return nil;}UIImage *image=[UIImage imageWithCGImage:thumb];CGImageRelease(thumb);NSData *jpeg=UIImageJPEGRepresentation(image,.78);if(jpeg.length>2*1024*1024)jpeg=UIImageJPEGRepresentation(image,.5);if(!jpeg||jpeg.length>2*1024*1024){if(error)*error=Err(@"图片压缩后超过 2 MB，请换用较小图片");return nil;}resolved=@{@"path":entry[@"path"],@"kind":@"image",@"data":[jpeg base64EncodedStringWithOptions:0],@"mime":@"image/jpeg",@"bytes":@(jpeg.length),@"referenceOnly":@YES};
