 for(NSString *key in @[@"start_line",@"line_count"])if(arguments[key]&&(![arguments[key] isKindOfClass:NSNumber.class]||[arguments[key] doubleValue]!=[arguments[key] integerValue]||[arguments[key] integerValue]<1)){if(error)*error=Err(@"行号与行数应为正整数。");return nil;}
 NSString *text=entry[@"content"];if(entry[@"localSnapshot"]){NSDictionary *snapshot=entry[@"localSnapshot"];NSString *path=TFAIAttachmentLocalPath(snapshot,error);if(!path)return nil;NSData *data=[NSData dataWithContentsOfFile:path options:NSDataReadingMappedIfSafe error:error];if(!data||![Hash(data) isEqual:snapshot[@"sha256"]]){if(error)*error=Err(@"附件副本已变化，请重新导入确认");return nil;}text=[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding];if(!text){if(error)*error=Err(@"附件文本编码不符");return nil;}}if(TFAIAttachmentSensitive(text)){if(error)*error=Err(@"附件含疑似密钥，已停止发送。");return nil;}
 NSArray *lines=[text componentsSeparatedByString:@"\n"];NSUInteger start=arguments[@"start_line"]?[arguments[@"start_line"] unsignedIntegerValue]:1,count=arguments[@"line_count"]?MIN(120,[arguments[@"line_count"] unsignedIntegerValue]):120;
 if(start>lines.count){if(error)*error=Err(@"起始行超过附件范围。");return nil;}
 NSMutableArray *out=[NSMutableArray new];NSUInteger bytes=0,next=start;
 for(NSUInteger i=start-1;i<MIN(lines.count,start-1+count);i++){NSString *line=lines[i];NSUInteger size=[line lengthOfBytesUsingEncoding:NSUTF8StringEncoding]+1;if(bytes+size>16384){if(!out.count){if(error)*error=Err(@"单行超过 16 KB，请拆分附件后重新选择。");return nil;}break;}[out addObject:line];bytes+=size;next=i+2;}
 return @{@"id":identifier,@"path":entry[@"path"]?:@"附件",@"start_line":@(start),@"end_line":@(next-1),@"total_lines":@(lines.count),@"next_line":next<=lines.count?@(next):NSNull.null,@"content":[out componentsJoinedByString:@"\n"],@"snapshot":@YES};
}
